79	function getAboutHeroSloganElement(): HTMLElement | null {
80	  if (aboutHeroSloganElement?.isConnected) {
81	    return aboutHeroSloganElement;
82	  }
83	  aboutHeroSloganElement = document.querySelector<HTMLElement>(
84	    ABOUT_HERO_SLOGAN_SELECTOR,
85	  );
86	  return aboutHeroSloganElement;
