99	function setAboutHeroSloganSurfaceAlpha(progress: number): void {
100	  const element = getAboutHeroSloganElement();
101	  if (!element) return;
102	  const clampedProgress = Math.max(0, Math.min(1, progress));
103	  const alpha =
104	    ABOUT_HERO_SLOGAN_ALPHA_MIN +
105	    ABOUT_HERO_SLOGAN_ALPHA_SPAN * clampedProgress;
106	  element.style.setProperty(ABOUT_HERO_SLOGAN_ALPHA_PROPERTY, alpha.toFixed(4));
107	}
108	
109	function resetAboutHeroSloganSurfaceAlpha(): void {
110	  const element = getAboutHeroSloganElement();
111	  if (!element) return;
112	  element.style.setProperty(
113	    ABOUT_HERO_SLOGAN_ALPHA_PROPERTY,
114	    String(ABOUT_HERO_SLOGAN_ALPHA_MIN),
115	  );
116	}
117	
118	function setAboutJourneySurfaceAlpha(alpha: number): void {
119	  const element = getAboutJourneySurfaceElement();
120	  if (!element) return;
121	  element.style.setProperty(ABOUT_JOURNEY_SURFACE_ALPHA_PROPERTY, alpha.toFixed(4));
122	}
