135	    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
136	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN +
137	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
138	  setAboutJourneySurfaceAlpha(alpha);
139	}
