141	function syncAboutAwardsSurfaceAlpha(progress: number): void {
142	  const clampedProgress = Math.max(0, Math.min(1, progress));
143	  const alpha =
144	    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
145	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * 2 +
146	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
147	  setAboutJourneySurfaceAlpha(alpha);
