161	function syncAboutHeroSlogan(progress: number): void {
162	  const top = document.querySelector<HTMLElement>(ABOUT_HERO_SLOGAN_TOP_SELECTOR);
163	  if (!top) return;
164	
165	  const textItems = Array.from(
166	    document.querySelectorAll<HTMLElement>(ABOUT_HERO_SLOGAN_TEXT_SELECTOR),
167	  );
168	  const shouldShow =
169	    progress >= ABOUT_HERO_SLOGAN_REVEAL_START &&
170	    progress < ABOUT_HERO_SLOGAN_REVEAL_END;
171	
172	  if (aboutSceneDomState.isHeroSloganVisible === shouldShow) return;
173	  aboutSceneDomState.isHeroSloganVisible = shouldShow;
174	  aboutSceneDomState.heroSloganTimers = clearTimers(
175	    aboutSceneDomState.heroSloganTimers,
176	  );
177	
178	  if (shouldShow) {
179	    BlockReveal.reveal(top);
180	    TextReveal.setVisibleOff(textItems);
181	    textItems.forEach((item, index) => {
182	      const timerId = window.setTimeout(() => {
183	        TextReveal.setVisibleOn(item);
184	      }, index * ABOUT_HERO_SLOGAN_REVEAL_STAGGER_SECONDS * 1000);
185	      aboutSceneDomState.heroSloganTimers.push(timerId);
186	    });
187	    return;
188	  }
189	
190	  textItems
191	    .slice()
192	    .reverse()
193	    .forEach((item, index) => {
194	      const timerId = window.setTimeout(() => {
195	        TextReveal.setVisibleOff(item);
196	      }, index * ABOUT_HERO_SLOGAN_REVEAL_STAGGER_SECONDS * 1000);
197	      aboutSceneDomState.heroSloganTimers.push(timerId);
198	    });
199	
200	  const hideTimerId = window.setTimeout(() => {
201	    BlockReveal.hide(top);
202	  }, textItems.length * ABOUT_HERO_SLOGAN_REVEAL_STAGGER_SECONDS * 1000);
203	  aboutSceneDomState.heroSloganTimers.push(hideTimerId);
204	}
205	
206	function disposeAboutHeroSlogan(): void {
207	  aboutSceneDomState.isHeroSloganVisible = false;
208	  aboutSceneDomState.heroSloganTimers = clearTimers(
209	    aboutSceneDomState.heroSloganTimers,
210	  );
211	
212	  const top = document.querySelector<HTMLElement>(ABOUT_HERO_SLOGAN_TOP_SELECTOR);
213	  if (!top) return;
214	  const textItems = Array.from(
215	    document.querySelectorAll<HTMLElement>(ABOUT_HERO_SLOGAN_TEXT_SELECTOR),
216	  );
217	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
218	  BlockReveal.hide(top);
219	}
