221	function syncAboutContactHead(progress: number): void {
222	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
223	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
224	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
225	  if (!section || !head || !actions) return;
226	
227	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
228	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
229	
230	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
231	  aboutSceneDomState.isContactHeadVisible = shouldShow;
232	  aboutSceneDomState.contactHeadTimers = clearTimers(
233	    aboutSceneDomState.contactHeadTimers,
234	  );
235	
236	  if (shouldShow) {
237	    section.dataset.active = "true";
238	    head.dataset.active = "true";
239	    actions.dataset.active = "true";
240	    TextReveal.setVisibleOff(textItems);
241	    textItems.forEach((item, index) => {
242	      const timerId = window.setTimeout(() => {
243	        TextReveal.setVisibleOn(item);
244	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
245	      aboutSceneDomState.contactHeadTimers.push(timerId);
246	    });
247	    return;
248	  }
249	
250	  textItems.forEach((item) => {
251	    TextReveal.setVisibleOff(item);
252	  });
253	  section.dataset.active = "false";
254	  head.dataset.active = "false";
255	  actions.dataset.active = "false";
256	}
