258	function disposeAboutContactHead(): void {
259	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
260	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
261	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
262	  if (!section || !head || !actions) return;
263	
264	  aboutSceneDomState.isContactHeadVisible = false;
265	  aboutSceneDomState.contactHeadTimers = clearTimers(
266	    aboutSceneDomState.contactHeadTimers,
267	  );
268	  section.dataset.active = "false";
269	  head.dataset.active = "false";
270	  actions.dataset.active = "false";
271	
272	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
273	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
274	}
