9	const OBSERVE_DEFAULTS = {
10	  enabled: true,
11	  threshold: 0,
12	  rootMargin: "18% 0px -18% 0px",
13	  once: false,
14	  revealWhenObserverUnavailable: true,
15	  revealWhenObserverDisabled: false,
16	} as const;
17	
18	const DIRECTIONAL_BOUNDS = {
19	  down: {
20	    enterBottomExpandRatio: 0.02,
21	    leaveTopCutoffRatio: 0.28,
22	  },
23	  up: {
24	    enterTopExpandRatio: 0.18,
25	    leaveBottomCutoffRatio: 0.1,
