107	    sceneElements: ReadonlyMap<TSceneKey, ScrollSceneElementEntry>,
108	    optionsByScene?: Readonly<
109	      Partial<Record<TSceneKey, ScrollSceneProgressOptions>>
110	    >,
111	  ): TSceneKey | null {
112	    const viewportHeight = this._getViewportHeight();
113	    const viewportCenter = viewportHeight / 2;
114	    let activeSceneKey: TSceneKey | null = null;
115	    let bestScore = Number.POSITIVE_INFINITY;
116	
117	    sceneElements.forEach((entry, sceneKey) => {
118	      const options = optionsByScene?.[sceneKey];
119	      if (this._resolveActivationMode(options) === "sectionTop") {
120	        return;
121	      }
122	
123	      const rect = entry.element.getBoundingClientRect();
124	      const intersectsViewport = rect.bottom > 0 && rect.top < viewportHeight;
125	      const distanceToCenter = Math.abs(
126	        rect.top + rect.height / 2 - viewportCenter,
127	      );
128	      const visibilityPenalty = intersectsViewport ? 0 : viewportHeight * 4;
129	      const score = visibilityPenalty + distanceToCenter;
130	      if (score >= bestScore) {
131	        return;
132	      }
133	
134	      bestScore = score;
135	      activeSceneKey = sceneKey;
136	    });
137	
138	    if (activeSceneKey) {
139	      return activeSceneKey;
140	    }
141	    return this._resolveNearestSceneKey(sceneElements);
142	  }
143	
144	  private _resolveNearestSceneKey<TSceneKey extends string>(
145	    sceneElements: ReadonlyMap<TSceneKey, ScrollSceneElementEntry>,
146	  ): TSceneKey | null {
147	    let firstSceneKey: TSceneKey | null = null;
148	    sceneElements.forEach((_entry, sceneKey) => {
149	      if (firstSceneKey) {
150	        return;
151	      }
152	      firstSceneKey = sceneKey;
153	    });
154	    return firstSceneKey;
155	  }
156	
157	  private _resolveActivationMode(
158	    options?: ScrollSceneProgressOptions,
159	  ): ScrollSceneActivationMode {
160	    return options?.activationMode ?? "viewportCenter";
161	  }
162	
163	  private _resolveActivationOffset(
164	    options?: ScrollSceneProgressOptions,
165	  ): number {
166	    const viewportHeight = this._getViewportHeight();
167	    const ratio = Helpers.clamp01(options?.activationOffsetRatio ?? 0);
168	    return viewportHeight * ratio;
169	  }
170	}
