172	class ScrollSceneProgressRuntime {
173	  private readonly _getViewportHeight: () => number;
174	
175	  constructor(getViewportHeight: () => number) {
176	    this._getViewportHeight = getViewportHeight;
177	  }
178	
179	  resolveSectionProgress(
180	    element: HTMLElement,
181	    options?: ScrollSceneProgressOptions,
182	  ): number {
183	    const rawProgress = this._resolveRawSectionProgress(element, options);
184	    const clampedRaw = Helpers.clamp01(rawProgress);
185	    const startRatio = this._clampRatio(options?.progressStart ?? 0.04);
186	    const endRatio = this._clampRatio(options?.progressEnd ?? 0.96);
187	    const span = Math.max(endRatio - startRatio, 0.01);
188	    const normalized = Math.max(
189	      0,
190	      Math.min(1, (clampedRaw - startRatio) / span),
191	    );
192	    const power = this._resolveProgressPower(options);
193	    return Math.pow(normalized, power);
194	  }
195	
196	  private _resolveRawSectionProgress(
197	    element: HTMLElement,
198	    options?: ScrollSceneProgressOptions,
199	  ): number {
200	    if (options?.progressMode === "top") {
201	      return this._resolveTopAnchoredProgress(element);
202	    }
203	    return this._resolveViewportProgress(element);
204	  }
205	
206	  private _resolveViewportProgress(element: HTMLElement): number {
207	    const rect = element.getBoundingClientRect();
208	    const viewportHeight = this._getViewportHeight();
209	    const start = viewportHeight;
210	    const end = -Math.max(rect.height - viewportHeight, 0);
211	    const travel = Math.max(start - end, 1);
212	    return (start - rect.top) / travel;
213	  }
214	
215	  private _resolveTopAnchoredProgress(element: HTMLElement): number {
216	    const rect = element.getBoundingClientRect();
217	    const viewportHeight = this._getViewportHeight();
218	    const travel =
219	      rect.height <= viewportHeight
220	        ? Math.max(rect.height, 1)
221	        : Math.max(rect.height - viewportHeight, 1);
222	    return -rect.top / travel;
223	  }
224	
225	  private _resolveProgressPower(options?: ScrollSceneProgressOptions): number {
226	    const value = options?.progressPower ?? 1.12;
227	    if (!Number.isFinite(value)) {
228	      return 1.12;
229	    }
230	    return Math.max(value, 0.1);
231	  }
232	
233	  private _clampRatio(value: number): number {
234	    return Helpers.clamp01(value);
235	  }
236	}
