238	export class ScrollSceneRuntime {
239	  private _root: ParentNode | null = null;
240	  private _cleanup: (() => void) | null = null;
241	  private _shellCleanupList: Array<() => void> = [];
242	  private _frameId = 0;
243	  private _isDirty = false;
244	  private _activeSceneKey: string | null = null;
245	  private readonly _progressState = new Map<string, ScrollSceneProgressState>();
246	  private readonly _activationRuntime = new ScrollSceneActivationRuntime(
247	    this._getViewportHeight.bind(this),
248	  );
249	  private readonly _progressRuntime = new ScrollSceneProgressRuntime(
250	    this._getViewportHeight.bind(this),
251	  );
252	
253	  setRoot(root?: ParentNode | null): void {
254	    this._root = root ?? null;
255	  }
256	
257	  start<TSceneKey extends string>(
258	    selectorByScene: Readonly<Partial<Record<TSceneKey, string>>>,
259	    applyProgress: (sceneKey: TSceneKey, progress: number) => void,
260	    optionsByScene?: Readonly<
261	      Partial<Record<TSceneKey, ScrollSceneProgressOptions>>
262	    >,
263	    runtimeOptions?: {
264	      skipInitialSync?: boolean;
265	    },
266	  ): void {
267	    this.dispose();
268	    const sceneElements = this._resolveSceneElements(selectorByScene);
269	    this._setupSceneShells(sceneElements, optionsByScene);
270	
271	    const updateTarget = (): void => {
272	      const activeSceneKey = this._activationRuntime.resolveActiveSceneKey(
273	        sceneElements,
274	        optionsByScene,
275	      );
276	      if (!activeSceneKey) return;
277	      const element = sceneElements.get(activeSceneKey)?.element;
278	      if (!element) return;
279	      const nextTarget = this._progressRuntime.resolveSectionProgress(
280	        element,
281	        optionsByScene?.[activeSceneKey],
282	      );
283	      const now = this._getNow();
284	      const didSceneChange = this._activeSceneKey !== activeSceneKey;
285	      const state = this._resolveProgressState(activeSceneKey, now, nextTarget);
286	      state.target = nextTarget;
287	      if (didSceneChange) {
288	        state.display = nextTarget;
289	      }
290	      state.updatedAt = now;
291	      if (
292	        isDebugSceneKey(activeSceneKey) &&
293	        (didSceneChange ||
294	          shouldLogDebugSceneProgress(
295	            debugTargetLogKeyByScene,
296	            activeSceneKey,
297	            "target",
298	            nextTarget,
299	          ))
300	      ) {
301	        const rect = element.getBoundingClientRect();
302	        Logger.info(CLASS, "updateTarget", `Resolved active debug scene ${activeSceneKey}.`, {
303	          sceneKey: activeSceneKey,
304	          rectTop: Number(rect.top.toFixed(2)),
305	          rectHeight: Number(rect.height.toFixed(2)),
306	          target: Number(nextTarget.toFixed(4)),
307	          display: Number(state.display.toFixed(4)),
308	          didSceneChange,
309	          scrollSpan: element.style.getPropertyValue("--scene-shell-span") || null,
310	        });
311	      }
312	      this._activeSceneKey = activeSceneKey;
313	    };
314	
315	    const animateProgress = (): void => {
316	      this._frameId = 0;
317	      const activeSceneKey = this._activeSceneKey as TSceneKey | null;
318	      if (!activeSceneKey) return;
319	
320	      const state = this._progressState.get(activeSceneKey);
321	      if (!state) return;
322	
323	      const options = optionsByScene?.[activeSceneKey];
324	      const now = this._getNow();
325	      const deltaMs = Math.max(now - state.updatedAt, 16.67);
326	      state.updatedAt = now;
327	
328	      const lagMs = this._resolveProgressLag(options);
329	      const alpha = 1 - Math.exp(-deltaMs / lagMs);
330	      state.display += (state.target - state.display) * alpha;
331	      if (Math.abs(state.target - state.display) < 0.001) {
332	        state.display = state.target;
333	      }
334	
335	      applyProgress(activeSceneKey, state.display);
336	      if (
337	        isDebugSceneKey(activeSceneKey) &&
338	        shouldLogDebugSceneProgress(
339	          debugDisplayLogKeyByScene,
340	          activeSceneKey,
341	          "display",
342	          state.display,
343	        )
344	      ) {
345	        Logger.info(CLASS, "animateProgress", `Animating debug scene ${activeSceneKey}.`, {
346	          sceneKey: activeSceneKey,
347	          target: Number(state.target.toFixed(4)),
348	          display: Number(state.display.toFixed(4)),
349	          deltaMs: Number(deltaMs.toFixed(2)),
350	          lagMs,
351	        });
352	      }
353	
354	      if (this._isDirty || Math.abs(state.target - state.display) >= 0.001) {
355	        this._requestFrame(animateProgress);
356	      }
357	      this._isDirty = false;
358	    };
359	
360	    const requestSync = (): void => {
361	      updateTarget();
362	      this._isDirty = true;
363	      this._requestFrame(animateProgress);
364	    };
365	
366	    const onScroll = (): void => requestSync();
367	    const onResize = (): void => requestSync();
368	    window.addEventListener("scroll", onScroll, { passive: true });
369	    window.addEventListener("resize", onResize);
370	    if (runtimeOptions?.skipInitialSync !== true) {
371	      requestSync();
372	    }
373	
374	    this._cleanup = () => {
375	      this._cancelFrame();
376	      window.removeEventListener("scroll", onScroll);
377	      window.removeEventListener("resize", onResize);
378	    };
379	  }
380	
381	  dispose(): void {
382	    this._cleanup?.();
383	    this._cleanup = null;
384	    this._shellCleanupList.forEach((cleanup) => cleanup());
385	    this._shellCleanupList = [];
386	    this._cancelFrame();
387	    this._progressState.clear();
388	    this._activeSceneKey = null;
389	    this._isDirty = false;
390	  }
391	
392	  private _setupSceneShells<TSceneKey extends string>(
393	    sceneElements: ReadonlyMap<TSceneKey, ScrollSceneElementEntry>,
394	    optionsByScene?: Readonly<
395	      Partial<Record<TSceneKey, ScrollSceneProgressOptions>>
396	    >,
397	  ): void {
398	    sceneElements.forEach(({ element }, sceneKey) => {
399	      const scrollSpanVh = optionsByScene?.[sceneKey]?.scrollSpanVh;
400	      if (
401	        typeof scrollSpanVh !== "number" ||
402	        !Number.isFinite(scrollSpanVh) ||
403	        scrollSpanVh <= 0
404	      ) {
405	        return;
406	      }
407	      this._shellCleanupList.push(
408	        this._applySceneShell(element, Math.round(scrollSpanVh)),
409	      );
410	      if (isDebugSceneKey(sceneKey)) {
411	        Logger.info(CLASS, "_setupSceneShells", `Applied scene shell to ${sceneKey}.`, {
412	          sceneKey,
413	          scrollSpanVh: Math.round(scrollSpanVh),
414	          selector: element.getAttribute("data-scene"),
415	          className: element.className,
416	        });
417	      }
418	    });
419	  }
420	
421	  private _resolveSceneElements<TSceneKey extends string>(
422	    selectorByScene: Readonly<Partial<Record<TSceneKey, string>>>,
423	  ): Map<TSceneKey, ScrollSceneElementEntry> {
424	    const sceneElements = new Map<TSceneKey, ScrollSceneElementEntry>();
425	    const entries = Object.entries(selectorByScene) as Array<
426	      [TSceneKey, string | undefined]
427	    >;
428	    entries.forEach(([sceneKey, selector]) => {
429	      if (typeof selector !== "string") return;
430	      const element = (this._root ?? document).querySelector<HTMLElement>(selector);
431	      if (!element) return;
432	      sceneElements.set(sceneKey as TSceneKey, {
433	        element,
434	      });
435	    });
436	    return sceneElements;
437	  }
438	
439	  private _applySceneShell(
440	    element: HTMLElement,
441	    scrollSpanVh: number,
442	  ): () => void {
443	    const shellClass = "scene-shell";
444	
445	    element.classList.add(shellClass);
446	    element.style.setProperty("--scene-shell-span", `${scrollSpanVh}vh`);
447	
448	    return () => {
449	      element.classList.remove(shellClass);
450	      element.style.removeProperty("--scene-shell-span");
451	    };
452	  }
453	
454	  private _resolveProgressState<TSceneKey extends string>(
455	    sceneKey: TSceneKey,
456	    now: number,
457	    initialProgress = 0,
458	  ): ScrollSceneProgressState {
459	    const existing = this._progressState.get(sceneKey);
460	    if (existing) return existing;
461	    const clampedInitialProgress = Helpers.clamp01(initialProgress);
462	    const next = {
463	      target: clampedInitialProgress,
464	      display: clampedInitialProgress,
465	      updatedAt: now,
466	    };
467	    this._progressState.set(sceneKey, next);
468	    return next;
469	  }
470	
471	  private _resolveProgressLag(options?: ScrollSceneProgressOptions): number {
472	    const value = options?.progressLagMs ?? 260;
473	    if (!Number.isFinite(value)) return 260;
474	    return Math.max(value, 16);
475	  }
476	
477	  private _requestFrame(callback: () => void): void {
478	    if (this._frameId !== 0) return;
479	    this._frameId = window.requestAnimationFrame(callback);
480	  }
481	
482	  private _cancelFrame(): void {
483	    if (this._frameId === 0) return;
484	    window.cancelAnimationFrame(this._frameId);
485	    this._frameId = 0;
486	  }
487	
488	  private _getNow(): number {
489	    if (typeof performance !== "undefined" && typeof performance.now === "function") {
490	      return performance.now();
491	    }
492	    return Date.now();
493	  }
494	
495	  private _getViewportHeight(): number {
496	    return Math.max(
497	      ResponsiveRuntime.getDefault().getSnapshot().viewportHeight || 0,
498	      1,
499	    );
500	  }
501	}
